import {useState} from \"react\";
import {useQuery,useQueryClient,useMutation} from \"@tanstack/react-query\";
import {useServerFn} from \"@tanstack/react-start\";
import {toast} from \"sonner\";
import {Button} from \"@/components/ui/button\";
import {Input} from \"@/components/ui/input\";
import {Label} from \"@/components/ui/label\";
import {useOrganization} from \"@/lib/org/org-context\";
import {queryCosts,simulatePricing,publishPrice,saveCostInput,captureProfitability} from \"@/lib/costs/costs.functions\";
import {money,type CostRow} from \"@/lib/costs/types\";
import {exportPartnerCsv} from \"@/lib/partners/export\";
import {CostShell,QueryState,Pages,Issues,asRows,inputClass} from \"./shared\";
const today=()=>new Date().toISOString().slice(0,10);
export function PricingPage(){return <CostShell title=\"Precificação\" permission=\"pricing.read\">{org=><Pricing org={org}/>}</CostShell>;}
function Pricing({org}:{org:string}){
 const{hasPermission}=useOrganization();const api=useServerFn(queryCosts),simulate=useServerFn(simulatePricing),publish=useServerFn(publishPrice),save=useServerFn(saveCostInput);const cache=useQueryClient();
 const[f,set]=useState<Record<string,string>>({mode:\"MARKUP\",cost:\"\",markup:\"\",price:\"\",target_margin_percent:\"\",commission_percent:\"0\",fee_percent:\"0\",tax_percent:\"0\",discount_percent:\"0\",freight:\"0\",other:\"0\"});
 const[p,setP]=useState({price_table_id:\"\",variant_id:\"\",unit_price:\"\",valid_from:today(),minimum_price:\"\"});const[search,setSearch]=useState(\"\");
 const options=useQuery({queryKey:[\"costs\",org,\"pricing_options\",search],queryFn:()=>api({data:{organizationId:org,kind:\"pricing_options\",filters:{query:search}}})});
 const tables=useQuery({queryKey:[\"costs\",org,\"price_tables\"],queryFn:()=>api({data:{organizationId:org,kind:\"price_tables\"}})});
 const simulation=useMutation({mutationFn:()=>simulate({data:{organizationId:org,values:Object.fromEntries(Object.entries(f).filter(([,v])=>v"'!=="").map(([k,v])=>[k,k==="mode"?v:Number(v)]))}}),onError:e=>toast.error(e.message)});
 const publication=useMutation({mutationFn:()=>publish({data:{organizationId:org,values:{price_table_id:p.price_table_id,variant_id:p.variant_id,unit_price:Number(p.unit_price),valid_from:p.valid_from,...(p.minimum_price!==""?{minimum_price:Number(p.minimum_price)}:{})}}}),onSuccess:()=>{toast.success("Nova vigência de preço publicada");void cache.invalidateQueries({queryKey:["costs",org]});void cache.invalidateQueries({queryKey:["price-tables"]});},onError:e=>toast.error(e.message)});
 const[rule,setRule]=useState<Record<string,string>>({channel:"MARKETPLACE",effective_from:today(),commission_percent:"0",tax_percent:"0",fee_percent:"0",freight_per_unit:"0",other_per_unit:"0",reason:"",store_id:"",variant_id:""});const[threshold,setThreshold]=useState("");
 const config=useMutation({mutationFn:(kind:"variable_rule"|"settings")=>save({data:{organizationId:org,kind,values:kind==="settings"?{low_margin_percent:threshold===""?null:Number(threshold)}:Object.fromEntries(Object.entries(rule).filter(([,v])=>v!==""))}}),onSuccess:()=>{toast.success("Configuração registrada");void cache.invalidateQueries({queryKey:["costs",org]});},onError:e=>toast.error(e.message)});
 const rules=useQuery({queryKey:["costs",org,"variable_rules"],queryFn:()=>api({data:{organizationId:org,kind:"variable_rules"}})});
 return <div className="space-y-6"><p className="text-muted-foreground">Custo não é preço. Markup é preço ÷ custo; margem bruta é (receita − COGS) ÷ receita. Simulações não alteram preços oficiais nem marketplaces.</p>
 {hasPermission("pricing.simulate")&&<form className="space-y-3 rounded border p-4" onSubmit={e=>{e.preventDefault();simulation.mutate();}}><h2 className="font-semibold">Simulador</h2><div className="grid gap-3 sm:grid-cols-3"><Label>Método<select className={inputClass} value={f.mode} onChange={e=>set({...f,mode:e.target.value})}><option value="MARKUP">Markup multiplicador</option><option value="PRICE">Preço informado</option><option value="TARGET_MARGIN">Margem de contribuição desejada</option></select></Label>{[["cost","Custo unitário R$"],...(f.mode==="MARKUP"?[["markup","Markup (ex.: 2,5)"]]:f.mode==="PRICE"?[["price","Preço R$"]]:[["target_margin_percent","Contribuição desejada %"]]),["commission_percent","Comissão %"],["fee_percent","Taxas %"],["tax_percent","Imposto estimado %"],["discount_percent","Desconto %"],["freight","Frete subsidiado R$/un"],["other","Outras despesas R$/un"]].map(([key,label])=><Label key={key}>{label}<Input required type="number" min="0" step="any" value={f[key]} onChange={e=>set({...f,[key]:e.target.value})}/></Label>)}</div><Button disabled={simulation.isPending}>Simular</Button>{simulation.error&&<p role="alert" className="text-destructive">{simulation.error.message}</p>}{simulation.data&&<div className="grid gap-3 sm:grid-cols-3">{[["suggested_price","Preço sugerido"],["gross_margin","Margem bruta R$"],["contribution","Contribuição R$"],["gross_margin_percent","Margem bruta %"],["contribution_margin_percent","Contribuição %"],["markup","Markup multiplicador"]].map(([key,label])=><div key={key}><p>{label}</p><strong>{key.endsWith("percent")||key==="markup"?Number(simulation.data[key]).toFixed(2):money(simulation.data[key])}</strong></div>)}</div>}</form>}
